14	public class BuildOwner {
15	
16	    public void service(@RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
17	            throws MissingOwnerFieldsException {
18	        Map<String, String> required = new LinkedHashMap<>();
19	        required.put("firstName", request.getFirstName());
20	        required.put("lastName", request.getLastName());
21	        required.put("address", request.getAddress());
22	        required.put("city", request.getCity());
23	        required.put("telephone", request.getTelephone());
24	        List<String> missing = required.entrySet().stream()
25	                .filter(e -> e.getValue() == null || e.getValue().isBlank())
26	                .map(Map.Entry::getKey).toList();
27	        if (!missing.isEmpty()) {
28	            throw new MissingOwnerFieldsException(missing);
29	        }
30	        built.set(ownerMapper.toOwner(request));
31	    }
32	}
